                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeKeystore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.write(
                     account: try FfiConverterString.lift(account),
                     secret: try FfiConverterData.lift(secret)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeKeystoreError_lower
            )
        },
