/**
 * One type on the clipboard. Text types are passed as UTF-8. `data` is `nil` for markers and
 * for types larger than the shell reads; `size` is then their size.
 */
public struct ClipEntry {
    /**
     * The platform's type name, such as `public.utf8-plain-text`.
     */
    public var typeId: String
    /**
     * The data, if read.
     */
    public var data: Data?
    /**
     * Size of the data in bytes.
     */
    public var size: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The platform's type name, such as `public.utf8-plain-text`.
         */typeId: String, 
        /**
         * The data, if read.
         */data: Data?, 
        /**
         * Size of the data in bytes.
         */size: UInt64) {
        self.typeId = typeId
        self.data = data
        self.size = size
    }
}

#if compiler(>=6)
extension ClipEntry: Sendable {}
#endif


extension ClipEntry: Equatable, Hashable {
    public static func ==(lhs: ClipEntry, rhs: ClipEntry) -> Bool {
        if lhs.typeId != rhs.typeId {
            return false
        }
        if lhs.data != rhs.data {
            return false
        }
        if lhs.size != rhs.size {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(typeId)
        hasher.combine(data)
        hasher.combine(size)
    }
}



