/**
 * The clipboard at one change.
 */
public struct ClipboardSnapshot {
    /**
     * Every type on the clipboard.
     */
    public var entries: [ClipEntry]
    /**
     * The application in front.
     */
    public var frontApp: SourceApp?
    /**
     * When the change was seen, in milliseconds since 1970.
     */
    public var capturedAtMs: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Every type on the clipboard.
         */entries: [ClipEntry], 
        /**
         * The application in front.
         */frontApp: SourceApp?, 
        /**
         * When the change was seen, in milliseconds since 1970.
         */capturedAtMs: UInt64) {
        self.entries = entries
        self.frontApp = frontApp
        self.capturedAtMs = capturedAtMs
