// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Why a copy was not kept.
 */

public enum DropReason {
    
    /**
     * Marked concealed (a password) by the source app.
     */
    case concealed
    /**
     * Marked transient by the source app.
     */
    case transient
    /**
     * Marked auto-generated.
     */
    case autoGenerated
    /**
     * Carries an ignored clipboard type.
     */
    case ignoredType
    /**
     * Copied from an ignored app.
     */
    case ignoredApp
    /**
     * Allow-list mode, and the app is not on the list.
     */
    case notAllowedApp
    /**
     * Matches an ignore pattern.
     */
    case ignoredPattern
    /**
     * Its kind of content is switched off.
     */
    case typeDisabled
    /**
     * Nothing Supercy can keep.
     */
    case unsupported
    /**
     * Larger than the limits.
     */
    case tooLarge
}


