@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDropReason: FfiConverterRustBuffer {
    typealias SwiftType = DropReason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DropReason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .concealed
        
        case 2: return .transient
        
        case 3: return .autoGenerated
        
        case 4: return .ignoredType
        
        case 5: return .ignoredApp
        
        case 6: return .notAllowedApp
        
        case 7: return .ignoredPattern
        
        case 8: return .typeDisabled
        
        case 9: return .unsupported
        
        case 10: return .tooLarge
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DropReason, into buf: inout [UInt8]) {
        switch value {
        
        
        case .concealed:
            writeInt(&buf, Int32(1))
        
        
        case .transient:
            writeInt(&buf, Int32(2))
        
        
        case .autoGenerated:
            writeInt(&buf, Int32(3))
        
        
        case .ignoredType:
            writeInt(&buf, Int32(4))
        
        
        case .ignoredApp:
            writeInt(&buf, Int32(5))
        
        
        case .notAllowedApp:
            writeInt(&buf, Int32(6))
        
        
        case .ignoredPattern:
            writeInt(&buf, Int32(7))
        
        
        case .typeDisabled:
            writeInt(&buf, Int32(8))
        
        
        case .unsupported:
            writeInt(&buf, Int32(9))
        
        
        case .tooLarge:
            writeInt(&buf, Int32(10))
        
        }
    }
}


