// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What happened to a snapshot.
 */

public enum IngestOutcome {
    
    /**
     * A new item; `evicted` items were removed by the limits.
     */
    case stored(
        /**
         * The new item's id.
         */id: String, 
        /**
         * Ids removed by the limits.
         */evicted: [String]
    )
    /**
     * The content was already there; that item moved to the top.
     */
    case updated(
        /**
         * The item's id.
         */id: String
    )
    /**
     * Nothing was kept.
     */
    case dropped(
        /**
         * Why.
         */reason: DropReason
    )
    /**
     * Recording is paused.
     */
    case paused
    /**
     * Skipped on request ("ignore the next copy").
     */
    case skipped
}


#if compiler(>=6)
extension IngestOutcome: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeIngestOutcome: FfiConverterRustBuffer {
    typealias SwiftType = IngestOutcome

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> IngestOutcome {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .stored(id: try FfiConverterString.read(from: &buf), evicted: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 2: return .updated(id: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .dropped(reason: try FfiConverterTypeDropReason.read(from: &buf)
        )
        
        case 4: return .paused
        
        case 5: return .skipped
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: IngestOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .stored(id,evicted):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            FfiConverterSequenceString.write(evicted, into: &buf)
            
        
        case let .updated(id):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .dropped(reason):
            writeInt(&buf, Int32(3))
            FfiConverterTypeDropReason.write(reason, into: &buf)
            
        
        case .paused:
            writeInt(&buf, Int32(4))
        
        
        case .skipped:
            writeInt(&buf, Int32(5))
        
        }
    }
}


