         */text: String
    )
    /**
     * Rich text; `plain` is for plain-text paste.
     */
    case richText(
        /**
         * RTF source.
         */rtf: Data?, 
        /**
         * HTML source.
         */html: String?, 
        /**
         * Plain-text form.
         */plain: String
    )
    /**
     * A link.
     */
    case url(
        /**
         * The URL.
         */url: String, 
        /**
         * Its title, if known.
         */title: String?
    )
    /**
     * An image.
     */
    case image(
        /**
         * Encoding.
         */format: ImageFormat, 
        /**
         * Width in pixels (0 if unknown).
         */width: UInt32, 
        /**
         * Height in pixels (0 if unknown).
         */height: UInt32, 
        /**
         * The encoded image.
         */bytes: Data
    )
    /**
     * Copied files, by name.
     */
    case fileRef(
        /**
         * File names.
         */names: [String]
    )
}


