public struct FfiConverterTypePasteRepresentation: FfiConverterRustBuffer {
    typealias SwiftType = PasteRepresentation

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PasteRepresentation {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .plainText(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .richText(rtf: try FfiConverterOptionData.read(from: &buf), html: try FfiConverterOptionString.read(from: &buf), plain: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .url(url: try FfiConverterString.read(from: &buf), title: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .image(format: try FfiConverterTypeImageFormat.read(from: &buf), width: try FfiConverterUInt32.read(from: &buf), height: try FfiConverterUInt32.read(from: &buf), bytes: try FfiConverterData.read(from: &buf)
        )
        
        case 5: return .fileRef(names: try FfiConverterSequenceString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PasteRepresentation, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .plainText(text):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .richText(rtf,html,plain):
            writeInt(&buf, Int32(2))
            FfiConverterOptionData.write(rtf, into: &buf)
            FfiConverterOptionString.write(html, into: &buf)
            FfiConverterString.write(plain, into: &buf)
            
        
        case let .url(url,title):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(url, into: &buf)
            FfiConverterOptionString.write(title, into: &buf)
            
        
        case let .image(format,width,height,bytes):
            writeInt(&buf, Int32(4))
            FfiConverterTypeImageFormat.write(format, into: &buf)
            FfiConverterUInt32.write(width, into: &buf)
            FfiConverterUInt32.write(height, into: &buf)
            FfiConverterData.write(bytes, into: &buf)
            
        
        case let .fileRef(names):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(names, into: &buf)
            
        }
    }
}


