/**
 * What went wrong, with a message the shell can show.
 */
public enum SupercyError: Swift.Error {

    
    
    /**
     * The history exists but its key is missing from the keychain.
     */
    case KeyMissing(
        /**
         * What happened and what to do.
         */message: String
    )
    /**
     * Another Supercy process has the history open.
     */
    case Locked(
        /**
         * What happened and what to do.
         */message: String
    )
    /**
     * The history was written by a newer Supercy.
     */
    case TooNew(
        /**
         * What happened and what to do.
         */message: String
    )
    /**
     * A setting is out of range.
     */
    case InvalidSetting(
        /**
         * Which setting and its range.
         */message: String
    )
    /**
     * The item no longer exists.
     */
    case NotFound(
        /**
         * What happened.
         */message: String
    )
    /**
     * A pin key is not a free letter from a to z, or the item is not pinned.
     */
    case InvalidPinKey(
        /**
         * What is wrong.
         */message: String
    )
    /**
     * An item id was not 32 hexadecimal digits.
     */
    case InvalidId(
        /**
         * What happened.
         */message: String
    )
    /**
     * The keychain failed.
     */
    case Keystore(
        /**
         * What happened.
         */message: String
    )
    /**
     * A pins file could not be read or written, or is not a pins file.
     */
    case PinsFile(
        /**
         * What is wrong.
         */message: String
    )
    /**
     * Storage or another internal failure.
     */
    case Internal(
        /**
         * What happened.
         */message: String
    )
}


